package tasks;

public class NestedIfwork1 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int num=88;
		if (num<=100) {
			if(num<100) {
			System.out.println(num+ " number is less than 100 ");
			}
			if(num>=50) {
				System.out.println(num+" number is greater than 50");
			}
			else {
				System.out.println(num+" number is less than to 50");
			}
		}
			else {
				System.out.println(num+" number is greater than to 100");
			}
		}

	}


